def compute_Last_Digit(a: int, b: int) -> int:
    if b <= a:
        return 1  # factorial(b)/factorial(a) = 1 if b <= a (empty product)
    product = 1
    for num in range(a + 1, b + 1):
        product *= num
    return product % 10


