def dif_Square(n: int) -> bool:
    # A number n can be represented as difference of squares (a^2 - b^2)
    # if and only if n is NOT congruent to 2 modulo 4.
    # Reason:
    # a^2 - b^2 = (a-b)(a+b)
    # Both (a-b) and (a+b) are integers of the same parity (both even or both odd),
    # so their product cannot be congruent to 2 mod 4.
    return n % 4 != 2


