def next_smallest_palindrome(n: int) -> int:
    def is_all_nines(s):
        return all(ch == '9' for ch in s)

    s = str(n)
    length = len(s)

    # If all 9's, the next palindrome is 10..01 (length+1)
    if is_all_nines(s):
        return int('1' + ('0' * (length - 1)) + '1')

    # Increment n by 1 because we want strictly greater palindrome
    n += 1
    s = str(n)
    length = len(s)

    half = length // 2
    odd = (length % 2 != 0)

    # Construct palindrome by mirroring left to right
    if odd:
        left = s[:half]
        middle = s[half]
        right = s[half + 1:]
    else:
        left = s[:half]
        middle = ''
        right = s[half:]

    # Create palindrome by mirroring left + middle
    if odd:
        palindrome = left + middle + left[::-1]
    else:
        palindrome = left + left[::-1]

    if int(palindrome) >= n:
        return int(palindrome)
    else:
        # Need to increment the middle part and mirror again
        if odd:
            # Increment left+middle as a number
            left_middle_num = int(left + middle)
            left_middle_num += 1
            left_middle_str = str(left_middle_num)
            # If length changed due to increment (e.g. 999 -> 1000)
            if len(left_middle_str) > len(left + middle):
                # This means palindrome length increases by 1
                # For example 999 -> 1001
                return int(left_middle_str + left_middle_str[:-1][::-1])
            left = left_middle_str[:-1]
            middle = left_middle_str[-1]
            palindrome = left + middle + left[::-1]
        else:
            # Increment left as a number
            left_num = int(left)
            left_num += 1
            left_str = str(left_num)
            if len(left_str) > len(left):
                # length increased, e.g. 99 -> 100
                # palindrome length increases by 1, e.g. 9999 -> 10001
                return int(left_str + left_str[:-1][::-1])
            palindrome = left_str + left_str[::-1]

        return int(palindrome)


