def find_solution(a, b, n):
    # We want to find non-negative integers x, y such that a*x + b*y = n.
    # Since we want the smallest non-negative x, we iterate x from 0 upwards.
    # For each x, check if (n - a*x) is divisible by b and if y = (n - a*x) // b is non-negative.
    if b == 0:
        # If b=0, then equation is a*x = n, so x = n/a if integer and non-negative.
        if a == 0:
            # a=0 and b=0 => equation 0= n, solution only if n=0.
            if n == 0:
                return (0, 0)
            else:
                return "No solution"
        if n % a == 0:
            x = n // a
            if x >= 0:
                return (x, 0)
        return "No solution"
    if a == 0:
        # a=0, so b*y = n
        if n % b == 0:
            y = n // b
            if y >= 0:
                return (0, y)
        return "No solution"

    # General case
    x = 0
    while True:
        val = n - a * x
        if val < 0:
            # Since x is increasing and a>0 or a<0:
            # if a>0 and val<0 then increasing x only decreases val further, no solution beyond.
            # if a<0, increasing x increases val, so loop might not terminate.
            # To handle negative a or b, we need to be careful.
            # We'll limit search to reasonable range to avoid infinite loop.
            # But since problem is ambiguous, let's handle negative a,b by searching over x from 0 up to a limit.
            break
        if val % b == 0:
            y = val // b
            if y >= 0:
                return (x, y)
        x += 1
        # To avoid infinite loop if no solution, set a max limit for x.
        # Let's limit to n+1 or abs(n)+1 to handle negative n.
        if x > abs(n) + 1000:
            break
    return "No solution"


