def find_exponentio(base: tuple[int, ...], exponent: tuple[int, ...]) -> tuple[int, ...]:
    base_int = int(''.join(map(str, base))) if base else 0
    exponent_int = int(''.join(map(str, exponent))) if exponent else 0
    result_int = pow(base_int, exponent_int)
    return tuple(int(d) for d in str(result_int))


