def get_total_number_of_sequences(n: int, m: int) -> int:
    from functools import lru_cache

    @lru_cache(None)
    def count_sequences(length: int, start_min: int) -> int:
        if length == 0:
            return 1
        total = 0
        # next element must be >= start_min
        for x in range(start_min, m + 1):
            # next start_min is at least 2*x
            total += count_sequences(length - 1, 2 * x)
        return total

    # first element can be from 1 to m
    total = 0
    for first in range(1, m + 1):
        total += count_sequences(n - 1, 2 * first)
    return total


