def find_Max(arr, start, end):
    if start == end:
        return arr[start]
    mid = (start + end) // 2
    # If mid element is greater than the next element,
    # mid element is the maximum
    if mid < end and arr[mid] > arr[mid + 1]:
        return arr[mid]
    # If mid element is smaller than the previous element,
    # previous element is the maximum
    if mid > start and arr[mid] < arr[mid - 1]:
        return arr[mid - 1]
    # If the mid element is greater than the start element,
    # maximum must be in the right half
    if arr[mid] > arr[start]:
        return find_Max(arr, mid + 1, end)
    # Else maximum is in the left half
    return find_Max(arr, start, mid - 1)


