def lucky_num(n):
    if n <= 0:
        return []
    # Start with a list of odd numbers from 1 upwards (classical sieve starts from 1)
    # We'll generate enough numbers to find at least n lucky numbers.
    # Since lucky numbers are sparse, we start with a list larger than n.
    # We will increase the range if needed.

    # Initial guess for range length:
    length = n * 10  
    while True:
        numbers = list(range(1, length + 1, 2))  # odd numbers only
        idx = 1  # the second number in the list (index 1) is the first "step"
        while idx < len(numbers):
            step = numbers[idx]
            if step > len(numbers):
                break
            # Remove every step-th number from the list, counting from 1-based index
            # i.e. remove numbers at positions step-1, 2*step-1, 3*step-1, ...
            # Note: positions are 0-based in Python, so remove indices step-1, 2*step-1,...
            # But after removals, indices shift. So better remove from the end to avoid shift.
            del_indices = list(range(step - 1, len(numbers), step))
            for i in reversed(del_indices):
                del numbers[i]
            idx += 1
            if len(numbers) >= n:
                # Continue sieving to refine the list, but if we already have enough numbers,
                # we could stop here and return the first n.
                # However, to be correct, we should finish the sieve steps.
                continue

        if len(numbers) >= n:
            return numbers[:n]
        length *= 2  # increase length and try again if not enough lucky numbers


