def compute_Last_Digit(a: int, b: int) -> int:
    # We want last digit of factorial(b) / factorial(a), assuming factorial(a) divides factorial(b).
    # factorial(b)/factorial(a) = (a+1)*(a+2)*...*b
    # We just need the last digit of the product of integers from a+1 to b.

    if b < a:
        # factorial(a) can't divide factorial(b) if b < a, but let's return 0 as no product.
        return 0
    if b == a:
        # factorial(b)/factorial(a) = 1
        return 1

    product_last_digit = 1
    for x in range(a+1, b+1):
        product_last_digit = (product_last_digit * (x % 10)) % 10
        # If last digit hits 0, product last digit is 0 forever
        if product_last_digit == 0:
            return 0

    return product_last_digit


