def dif_Square(n: int) -> bool:
    # A number n can be expressed as a difference of squares:
    # n = a^2 - b^2 = (a-b)(a+b)
    # So n must be representable as a product of two integers x and y with:
    # x = a-b, y = a+b, and both x and y have the same parity (both even or both odd)
    # Because a = (x+y)/2, b = (y-x)/2 must be integers.

    # Iterate over all divisors d of n (positive and negative)
    # For each divisor d, check if n/d is also integer.
    # Then check if d and n/d have the same parity.
    # If yes, return True.

    # Special handling for zero:
    # 0 = a^2 - a^2, so 0 can be represented trivially.
    if n == 0:
        return True

    abs_n = abs(n)
    for d in range(1, int(abs_n**0.5) + 1):
        if abs_n % d == 0:
            x, y = d, abs_n // d
            # Check parity for (x, y) and also for (-x, -y) since both can form pairs
            # Because n can be negative, we consider both sign options:
            # If n = x*y, then (a-b) = x, (a+b) = y or (a-b) = -x, (a+b) = -y
            # We only need to check parity of absolute values because parity is invariant under negation.

            # Check for (x, y)
            if (x + y) % 2 == 0:
                return True
            # Check for (y, x) - symmetric but redundant since both are divisors of n
            # Actually, since multiplication is commutative, no need to check swap.

    return False


