def next_smallest_palindrome(num: int) -> int:
    # Edge case: if num <= 0, there is no smaller positive palindrome
    # We'll allow negative numbers and zero, but palindromes are non-negative integers by usual definition.
    # For negative or zero input, return -1 to indicate no smaller palindrome exists.
    if num <= 0:
        return -1

    def is_palindrome(x: int) -> bool:
        s = str(x)
        return s == s[::-1]

    # Start from num-1 and go downwards until we find a palindrome.
    for candidate in range(num - 1, -1, -1):
        if is_palindrome(candidate):
            return candidate

    # If no palindrome found (should not happen for num > 0), return -1
    return -1


