def find_solution(a, b, n):
    # Try nonnegative x from 0 upwards
    for x in range(n // a + 1 if a != 0 else n + 1):
        # Check if (n - a*x) is divisible by b
        remainder = n - a * x
        if b == 0:
            # If b == 0, then equation reduces to a*x = n
            if remainder == 0:
                return ('x = ', x, ', y = ', 0)
            else:
                continue
        if remainder % b == 0:
            y = remainder // b
            return ('x = ', x, ', y = ', y)
    return None


