def min_flip_to_make_string_alternate(s: str) -> int:
    count_start_0 = 0
    count_start_1 = 0
    for i, ch in enumerate(s):
        expected_0 = '0' if i % 2 == 0 else '1'
        expected_1 = '1' if i % 2 == 0 else '0'
        if ch != expected_0:
            count_start_0 += 1
        if ch != expected_1:
            count_start_1 += 1
    return min(count_start_0, count_start_1)


