def lucky_num(n):
    # Start with a list of odd numbers starting from 1 (all odd numbers are candidates)
    arr = list(range(1, 2 * n * 10, 2))
    idx = 1
    while idx < len(arr):
        step = arr[idx]
        if step > len(arr):
            break
        # Remove every step-th element from the list, starting from index step-1
        del arr[step - 1::step]
        idx += 1
        if len(arr) >= n:
            # We cannot stop early here because the sieve changes the list dynamically
            # We need to run until idx reaches the end or step > len(arr)
            pass
    return arr[:n]


