def get_noOfways(n: int, m: int) -> int:
    # Number of ways to tile a 2 x n board using 2 x 1 tiles
    # m parameter is ignored since tile size is fixed as 2 x 1
    # The recurrence for the number of ways is:
    # dp[i] = dp[i-1] + dp[i-2]
    # with dp[0] = 1 (empty board), dp[1] = 1 (only vertical tiles)
    if n < 0:
        return 0
    if n == 0 or n == 1:
        return 1
    dp = [0] * (n + 1)
    dp[0] = 1
    dp[1] = 1
    for i in range(2, n + 1):
        dp[i] = dp[i-1] + dp[i-2]
    return dp[n]


