def compute_Last_Digit(a: int, b: int) -> int:
    low, high = min(a, b), max(a, b)
    # Compute last digit of product(low+1 * low+2 * ... * high)
    result = 1
    for x in range(low + 1, high + 1):
        result = (result * (x % 10)) % 10
        if result == 0:
            # Once last digit is zero, it won't change
            break
    return result


