def dif_Square(n: int) -> bool:
    # A number n can be expressed as a difference of two squares a² - b² = n
    # if and only if n is NOT congruent to 2 mod 4.
    # Explanation:
    # a² - b² = (a-b)(a+b)
    # Both (a-b) and (a+b) are integers, so n can be factored into two integers of the same parity.
    # The difference of two squares representation exists for all integers except those congruent to 2 mod 4.
    return n % 4 != 2


