from math import gcd

def find_solution(a: int, b: int, n: int):
    # Extended Euclidean Algorithm to find one solution (x0, y0) to a*x + b*y = gcd(a,b)
    def extended_gcd(aa, bb):
        if bb == 0:
            return (aa, 1, 0)
        g, x1, y1 = extended_gcd(bb, aa % bb)
        x = y1
        y = x1 - (aa // bb) * y1
        return g, x, y

    g, x0, y0 = extended_gcd(abs(a), abs(b))
    if n % g != 0:
        return None  # no solution

    # Scale the particular solution to the actual equation a*x + b*y = n
    x0 *= n // g
    y0 *= n // g

    # Adjust signs if a or b are negative
    if a < 0:
        x0 = -x0
    if b < 0:
        y0 = -y0

    # We want to find t such that:
    # x = x0 + t*(b/g) >= 0
    # y = y0 - t*(a/g) >= 0

    # Coefficients for parameter t
    k = b // g
    l = a // g

    # Compute bounds on t to keep x,y non-negative
    # x >= 0 => x0 + k*t >= 0 => t >= -x0/k if k>0 else t <= -x0/k
    # y >= 0 => y0 - l*t >= 0 => t <= y0/l if l>0 else t >= y0/l

    # Careful with division by zero (should not happen as g divides a and b)
    # But a or b can be zero: handle these cases separately

    if a == 0 and b == 0:
        return (0,0) if n == 0 else None
    if a == 0:
        # Equation: b*y = n => y = n/b if integer and y>=0
        if b != 0 and n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return None
    if b == 0:
        # Equation: a*x = n => x = n/a if integer and x>=0
        if a != 0 and n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return None

    # now a,b != 0

    # Determine ranges for t
    # Because k = b/g and l = a/g could be positive or negative, consider:

    # For x >= 0:
    if k > 0:
        t_min_x = (-x0 + k - 1) // k  # ceil division for t >= -x0/k
    else:
        # k < 0
        t_max_x = (-x0) // k  # floor division for t <= -x0/k

    # For y >= 0:
    if l > 0:
        t_max_y = y0 // l  # floor division for t <= y0/l
    else:
        # l < 0
        t_min_y = (y0 + (-l) - 1) // (-l)  # ceil division for t >= y0/l

    # Combine bounds carefully:

    # Initialize bounds as -inf to +inf
    t_min = -float('inf')
    t_max = float('inf')

    if k > 0:
        t_min = max(t_min, (-x0 + k - 1) // k)
    else:
        # k < 0
        t_max = min(t_max, (-x0) // k)

    if l > 0:
        t_max = min(t_max, y0 // l)
    else:
        t_min = max(t_min, (y0 + (-l) - 1) // (-l))

    if t_min > t_max:
        return None

    # Since t must be integer, pick any integer t in [t_min, t_max]
    # Choose t = t_min (smallest feasible)
    t = t_min if t_min != -float('inf') else 0
    if t < t_min:
        t = t_min
    if t > t_max:
        return None

    x = x0 + k * t
    y = y0 - l * t

    if x < 0 or y < 0:
        return None

    return (x, y)


