def permute_string(s):
    def backtrack(path, counter, length, result):
        if len(path) == length:
            result.append(''.join(path))
            return
        for ch in sorted(counter):
            if counter[ch] > 0:
                counter[ch] -= 1
                path.append(ch)
                backtrack(path, counter, length, result)
                path.pop()
                counter[ch] += 1

    from collections import Counter
    result = []
    counter = Counter(s)
    backtrack([], counter, len(s), result)
    return result


