def find_Max(arr):
    if not arr:
        return None  # or raise an error if empty input is invalid

    low, high = 0, len(arr) - 1

    # If array is not rotated (sorted ascending)
    if arr[low] < arr[high]:
        return arr[high]

    while low <= high:
        mid = (low + high) // 2
        # Check if mid is max
        if mid < high and arr[mid] > arr[mid + 1]:
            return arr[mid]
        if mid > low and arr[mid] < arr[mid - 1]:
            return arr[mid - 1]

        # Decide which side to go
        if arr[mid] >= arr[low]:
            # Left part is sorted, max must be in right part
            low = mid + 1
        else:
            high = mid - 1

    return arr[0]  # fallback, array has only one element


