def text_match(text):
    # The pattern matches 'a' followed by zero or more 'b's,
    # but only if not followed by another 'b'.
    # This means the substring ends with 'a' or some 'b's but no further 'b' after.
    pattern = r'a b* (?!b)'  # spaces added for clarity below

    # Remove spaces for actual regex
    pattern = r'ab*(?!b)'

    if re.search(pattern, text):
        return "Found a match!"
    else:
        return "Not matched!"


