def lucky_num(n):
    # Generate lucky numbers using the sieve method
    # Start with the list of odd numbers starting from 1
    numbers = list(range(1, 2*n*10, 2))  # heuristic upper bound
    idx = 1
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number starting from step-1 index (0-based)
        del numbers[step-1::step]
        idx += 1
        if len(numbers) >= n:
            # We can stop early only if we have at least n lucky numbers
            pass
    return numbers[:n]


