def compute_Last_Digit(a: int, b: int) -> int:
    # Since factorial(b)/factorial(a) = (a+1)*(a+2)*...*b,
    # we just need the last digit of the product of these integers.
    if a > b:
        return 0
    product = 1
    for x in range(a + 1, b + 1):
        product = (product * (x % 10)) % 10
        # If product ends with 0, early stop
        if product == 0:
            return 0
    return product


