def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # Edge case: if num < 9, next palindrome is num+1 (since single digit palindrome)
    if num < 9:
        return num + 1

    # Helper to check if all digits are 9
    if all(ch == '9' for ch in s):
        # next palindrome after 999..9 is 100..001 (length+1 digits)
        return int('1' + ('0' * (length - 1)) + '1')

    def make_palindrome(left, middle, odd_len):
        if odd_len:
            return int(left + middle + left[::-1])
        else:
            return int(left + left[::-1])

    odd_len = (length % 2 != 0)
    if odd_len:
        left = s[:length // 2]
        middle = s[length // 2]
        right = s[length // 2 + 1:]
    else:
        left = s[:length // 2]
        middle = ''
        right = s[length // 2:]

    pal = make_palindrome(left, middle, odd_len)

    if pal > num:
        return pal
    else:
        # Need to increment the middle part and mirror again
        if odd_len:
            # Increment middle digit plus left half as a number
            left_middle_num = int(left + middle)
            left_middle_num += 1
            left_middle_str = str(left_middle_num)
            # If length changed, means carry overflowed to more digits
            if len(left_middle_str) > len(left) + 1:
                # e.g. 999 -> 1000, palindrome will have length+1 digits
                return int('1' + ('0' * (length - 1)) + '1')
            left = left_middle_str[:-1]
            middle = left_middle_str[-1]
            return make_palindrome(left, middle, True)
        else:
            # Even length: increment left half, mirror again
            left_num = int(left)
            left_num += 1
            left_str = str(left_num)
            if len(left_str) > len(left):
                # e.g. 99 -> 100, palindrome will have length+1 digits
                return int('1' + ('0' * (length - 1)) + '1')
            return make_palindrome(left_str, '', False)


