def find_solution(a: int, b: int, n: int):
    if b == 0:
        if n % a == 0:
            return (n // a, 0)
        else:
            return None
    x = 0
    while a * x <= n:
        remainder = n - a * x
        if remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return (x, y)
        x += 1
    return None


