def even_binomial_Coeff_Sum(n: int) -> int:
    # Using the identity:
    # sum_{k even} C(n,k) = 2^(n-1) if n > 0
    # and sum_{k even} C(0,k) = C(0,0) = 1
    if n == 0:
        return 1
    return 2 ** (n - 1)


