def drop_empty(d):
    empty_values = {None, '', (), frozenset()}
    # Note: sets are mutable, so use frozenset for set() comparison
    # For lists and dicts, check explicitly
    def is_empty(value):
        if value in empty_values:
            return True
        if isinstance(value, (list, dict, set)):
            return len(value) == 0
        return False

    return {k: v for k, v in d.items() if not is_empty(v)}


