def find_Max(arr):
    if not arr:
        return None
    left, right = 0, len(arr) - 1
    # If array is not rotated (sorted ascending), the last element is max
    if arr[left] < arr[right]:
        return arr[right]
    # Binary search for the maximum element
    while left < right:
        mid = (left + right) // 2
        # If mid element is greater than the rightmost element,
        # max must be in mid...right
        if arr[mid] > arr[right]:
            left = mid + 1
        else:
            right = mid
    # left now points to the minimum element, max is just before it
    return arr[left - 1] if left > 0 else arr[-1]


