def reverse_Array_Upto_K(arr, k):
    # Reverse the array elements from start up to index k (inclusive).
    # If k is out of bounds, adjust to valid range.
    if not arr:
        return arr
    n = len(arr)
    if k < 0:
        k = 0
    elif k >= n:
        k = n - 1
    return arr[:k+1][::-1] + arr[k+1:]


