def filter_data(data, min_height=None, max_height=None, min_width=None, max_width=None):
    filtered_ids = []
    for student_id, attrs in data.items():
        height = attrs.get('height')
        width = attrs.get('width')
        if height is None or width is None:
            continue
        if (min_height is not None and height < min_height) or \
           (max_height is not None and height > max_height) or \
           (min_width is not None and width < min_width) or \
           (max_width is not None and width > max_width):
            continue
        filtered_ids.append(student_id)
    return filtered_ids


