def lucky_num(n):
    nums = list(range(1, 2 * n * 10))  # initial range; overshoot to ensure enough lucky numbers
    idx = 1
    while idx < len(nums) and len(nums) < n or idx < len(nums):
        step = nums[idx]
        if step > len(nums):
            break
        del nums[step - 1::step]
        idx += 1
        if len(nums) >= n and idx > len(nums):
            break
    return nums[:n]


