def dif_Square(n: int) -> bool:
    # A number n can be expressed as a difference of squares if and only if n is not congruent to 2 mod 4.
    # This comes from the identity:
    # a^2 - b^2 = (a+b)(a-b) = n
    # For n to be expressed as difference of two squares, n must not be 2 mod 4.
    return n % 4 != 2


