def find_solution(a, b, n):
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else "No solution"
    if a == 0:
        if n % b == 0 and n // b >= 0:
            return (0, n // b)
        return "No solution"
    x = 0
    while True:
        remainder = n - a * x
        if remainder < 0:
            break
        if remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return (x, y)
        x += 1
    return "No solution"


