def get_total_number_of_sequences(m: int, n: int) -> int:
    """
    Count sequences of length n over integers 1..m satisfying:
    - sequence is non-decreasing: seq[i] >= seq[i-1]
    - each element is at most double the previous element: seq[i] <= 2 * seq[i-1]

    Returns the count of all such sequences.
    """

    from functools import lru_cache

    # Handle edge case: if n == 0, only empty sequence counts as 1
    if n == 0:
        return 1

    @lru_cache(None)
    def dfs(pos: int, prev: int) -> int:
        if pos == n:
            return 1
        total = 0
        # next element must be in [prev, min(m, 2*prev)]
        start = prev
        end = min(m, 2 * prev)
        for nxt in range(start, end + 1):
            total += dfs(pos + 1, nxt)
        return total

    total_count = 0
    # first element can be anything from 1 to m
    for first in range(1, m + 1):
        total_count += dfs(1, first)

    return total_count


