def even_binomial_Coeff_Sum(n: int) -> int:
    # Sum of even binomial coefficients in nth row of Pascal's triangle
    # The sum of all binomial coefficients in row n is 2^n
    # The sum of binomial coefficients at even k in row n is 2^(n-1)
    # (for n >= 1; for n=0, the sum is 1)
    if n == 0:
        return 1
    return 2 ** (n - 1)


