def remove_column(data, index):
    if isinstance(data, list):
        # If elements of the list are lists, remove the element at index from each inner list
        # Also handle nested structures recursively
        result = []
        for item in data:
            if isinstance(item, list):
                # Remove element at index if possible
                if 0 <= index < len(item):
                    new_item = item[:index] + item[index+1:]
                else:
                    new_item = item[:]
                # Recursively process inner lists if any
                new_item = remove_column(new_item, index)
                result.append(new_item)
            else:
                # Recursively process non-list items
                result.append(remove_column(item, index))
        return result
    elif isinstance(data, dict):
        # Recursively process dictionary values
        return {k: remove_column(v, index) for k, v in data.items()}
    else:
        # For other data types, return as is
        return data


