def smallest_missing(arr, left, right):
    """
    Find the smallest positive integer missing from arr[left:right+1].
    """
    # Extract the relevant subarray
    subarr = arr[left:right+1]

    # Filter to keep only positive integers
    subarr = [x for x in subarr if x > 0]

    # Use a set for O(1) lookups
    s = set(subarr)

    # The smallest missing positive integer is at least 1
    i = 1
    while True:
        if i not in s:
            return i
        i += 1


