def dif_Square(n: int) -> bool:
    # A number n can be represented as a difference of two squares a^2 - b^2
    # if and only if n is not congruent to 2 mod 4.
    # This is because:
    # a^2 - b^2 = (a+b)(a-b)
    # Both (a+b) and (a-b) are integers and have the same parity.
    # The product of two integers with the same parity is never congruent to 2 mod 4.
    return n % 4 != 2


