def next_smallest_palindrome(n: int) -> int | None:
    if n <= 0:
        return None

    def is_palindrome(x: int) -> bool:
        s = str(x)
        return s == s[::-1]

    candidate = n + 1
    while True:
        if is_palindrome(candidate):
            return candidate
        candidate += 1


