def get_total_number_of_sequences(n: int) -> int:
    """
    Returns the total number of strictly increasing sequences that can be formed
    with elements from 1 to n (inclusive).

    Explanation:
    - Each strictly increasing sequence corresponds to a non-empty subset of {1,...,n}
      arranged in ascending order.
    - The number of non-empty subsets of an n-element set is 2^n - 1.
    """
    return (1 << n) - 1


