import re

def text_match_two_three(s: str, first_char: str, repeat_char: str) -> bool:
    """
    Check if the string `s` contains a substring starting with `first_char`
    followed by 2 or 3 repetitions of `repeat_char`.
    """
    pattern = re.escape(first_char) + re.escape(repeat_char) + '{2,3}'
    return bool(re.search(pattern, s))


