def find_Max(lst, start, end):
    # If the sublist is empty or invalid range, return None
    if start > end:
        return None
    # If sublist has one element
    if start == end:
        return lst[start]
    # If sublist is sorted (no rotation), max is at end
    if lst[start] < lst[end]:
        return lst[end]
    mid = (start + end) // 2
    # Check if mid is the max (greater than next element)
    if mid < end and lst[mid] > lst[mid + 1]:
        return lst[mid]
    # Check if mid-1 is max (greater than mid)
    if mid > start and lst[mid - 1] > lst[mid]:
        return lst[mid - 1]
    # Decide which side to recurse on
    if lst[mid] > lst[start]:
        # max must be in right half
        return find_Max(lst, mid + 1, end)
    else:
        # max must be in left half
        return find_Max(lst, start, mid - 1)


