def substract_elements(groups1, groups2):
    result = []
    for g1, g2 in zip(groups1, groups2):
        c1 = Counter(g1)
        c2 = Counter(g2)
        diff = c1 - c2  # subtract counts, only keep positives
        leftover = []
        for num, count in diff.items():
            leftover.extend([num] * count)
        result.append(leftover)
    return result


