def lucky_num(n):
    """
    Generate the first n lucky numbers using the lucky number sieve.

    The lucky number sieve:
    Start with the list of natural numbers starting at 1.
    Step 1: Remove every 2nd number.
    Step 2: The next remaining number after 1 is 3, remove every 3rd number.
    Step 3: The next remaining number after that is 7, remove every 7th number.
    Continue this process with the next remaining number as the step to remove numbers.

    Returns a list of the first n lucky numbers.
    """
    numbers = list(range(1, 10*n))  # initial range large enough to get n lucky numbers
    idx = 1  # Start from second number (index 1)

    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number from the list (1-based indexing)
        # We build a new list skipping these indices
        numbers = [num for i, num in enumerate(numbers, start=1) if i % step != 0]
        idx += 1
        if len(numbers) >= n and idx > n:  # optimization: stop if we have enough numbers and passed enough steps
            break
    return numbers[:n]


