def compute_Last_Digit(a: int, b: int) -> int:
    # The result is product of integers from a+1 to b
    # We want the last digit of that product
    if b < a:
        # factorial(b) / factorial(a) not defined if b < a, but let's return 0 as no product
        return 0
    product_last_digit = 1
    for num in range(a + 1, b + 1):
        product_last_digit = (product_last_digit * (num % 10)) % 10
        # Once product_last_digit is 0, it will remain 0
        if product_last_digit == 0:
            return 0
    return product_last_digit


