def dif_Square(n: int) -> bool:
    # n = a^2 - b^2 = (a-b)(a+b)
    # Let x = a-b, y = a+b, so n = x*y
    # a = (x+y)/2, b = (y-x)/2 must be integers
    # So x and y must be both even or both odd.
    # Therefore, can n be represented as product of two integers with same parity?

    # Special case: n = 0
    # 0 = a^2 - b^2 => a^2 = b^2 => a = ±b, so yes.
    if n == 0:
        return True

    # Check all factor pairs (x, y) of n
    # We'll check divisors d of n, and y = n//d
    # to find if x=d and y=n//d have same parity

    abs_n = abs(n)
    for d in range(1, int(abs_n**0.5) + 1):
        if abs_n % d == 0:
            x, y = d, abs_n // d

            # Check parity of x,y
            # If n < 0, the product x*y = -abs_n, so one factor must be negative:
            # We consider both (x,y) and (-x,-y) pairs to cover negative n.

            # Check (x,y) pair with sign to match n:
            # If n > 0, x*y = n, so (x,y) and (-x,-y) both valid
            # If n < 0, x*y = abs_n, so to get n = -abs_n, one factor negative:
            # So either (-x, y) or (x, -y)

            candidates = []
            if n > 0:
                candidates.append((x, y))
                candidates.append((-x, -y))
            else:
                candidates.append((-x, y))
                candidates.append((x, -y))

            for (xx, yy) in candidates:
                if (xx % 2) == (yy % 2):
                    # Then a=(x+y)/2 and b=(y-x)/2 are integers
                    return True
    return False


