def next_smallest_palindrome(num: int) -> int:
    def is_palindrome(x: int) -> bool:
        s = str(x)
        return s == s[::-1]

    # The next smallest palindrome strictly less than num
    # If num <= 0, no smaller palindrome positive number exists, 
    # so return None or 0 (choose 0)
    if num <= 0:
        return 0

    for candidate in range(num - 1, -1, -1):
        if is_palindrome(candidate):
            return candidate
    return 0  # fallback if something odd happens (should never reach here)


