def find_solution(a: int, b: int, n: int) -> tuple[int, int]:
    def extended_gcd(x, y):
        if y == 0:
            return (x, 1, 0)
        g, x1, y1 = extended_gcd(y, x % y)
        return (g, y1, x1 - (x // y) * y1)

    g, x, y = extended_gcd(a, b)
    if n % g != 0:
        # No solution exists if n is not divisible by gcd(a, b)
        # But the task doesn't specify what to do in that case.
        # We'll return None to indicate no solution.
        return None
    factor = n // g
    return (x * factor, y * factor)


