def get_total_number_of_sequences(n: int, m: int) -> int:
    from functools import lru_cache

    @lru_cache(None)
    def count_sequences(length: int, prev: int) -> int:
        if length == n:
            return 1
        total = 0
        start = prev * 2
        for nxt in range(start, m + 1):
            total += count_sequences(length + 1, nxt)
        return total

    total_sequences = 0
    for start_val in range(1, m + 1):
        total_sequences += count_sequences(1, start_val)
    return total_sequences


