def lucky_num(n):
    numbers = list(range(1, 2*n*10))  # start with a large enough range
    idx = 1
    while len(numbers) > n:
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number (1-based index)
        del numbers[step-1::step]
        idx += 1
    return numbers[:n]


