from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    # Split the input by spaces to get groups
    groups = paren_string.split()

    # For each group, track max depth by scanning characters without loops or recursion
    # Use map and reduce from functools to avoid explicit loops

    from functools import reduce

    def max_depth(group: str) -> int:
        # We process characters using reduce to maintain current depth and max depth
        # state = (current_depth, max_depth)
        def reducer(state, char):
            cur, mx = state
            if char == '(':
                cur += 1
                mx = max(mx, cur)
            elif char == ')':
                cur -= 1
            return (cur, mx)
        _, maximum = reduce(reducer, group, (0, 0))
        return maximum

    return list(map(max_depth, groups))


