from typing import List, Tuple

def parse_music(music_string: str) -> Tuple[List[int], str]:
    # Mapping from note string to beats
    beats_map = {'o': 4, 'o|': 2, '.|': 1}
    # Split the input string by spaces to get notes
    notes = music_string.split()
    # Map notes to beats without loops using map and list
    beats = list(map(beats_map.get, notes))

    # Count occurrences of each note without loops by using count method thrice
    count_o = notes.count('o')
    count_o_pipe = notes.count('o|')
    count_dot_pipe = notes.count('.|')

    # Determine most common note with tie-break by longest beat
    # Build tuples (count, beat, note) and pick max by count, then beat
    candidates = [
        (count_o, 4, 'o'),
        (count_o_pipe, 2, 'o|'),
        (count_dot_pipe, 1, '.|')
    ]
    most_common = max(candidates, key=lambda x: (x[0], x[1]))[2]

    # Fix for empty input: if no notes, return ([], '')
    if not notes:
        return [], ''

    return beats, most_common


