def monotonic(l):
    if isinstance(l, list):
        # Check duplicates
        if len(set(l)) != len(l):
            return False

        # Define helper to check monotonic increasing or decreasing recursively (no loops)
        def is_increasing(i=0):
            if i >= len(l) - 1:
                return True
            if l[i] >= l[i + 1]:
                return False
            return is_increasing(i + 1)

        def is_decreasing(i=0):
            if i >= len(l) - 1:
                return True
            if l[i] <= l[i + 1]:
                return False
            return is_decreasing(i + 1)

        if is_increasing() or is_decreasing():
            return True
        else:
            return False

    elif isinstance(l, str):
        # Check duplicates
        if len(set(l)) != len(l):
            return False

        # Check monotonic increasing (alphabetical)
        def is_increasing(i=0):
            if i >= len(l) - 1:
                return True
            if l[i] >= l[i + 1]:
                return False
            return is_increasing(i + 1)

        # Check monotonic decreasing (reverse alphabetical)
        def is_decreasing(i=0):
            if i >= len(l) - 1:
                return True
            if l[i] <= l[i + 1]:
                return False
            return is_decreasing(i + 1)

        if is_increasing() or is_decreasing():
            return True, l
        else:
            return False


