from collections import Counter

def search(lst):
    freq = Counter(lst)
    # For numeric input
    if isinstance(lst[0], int):
        # Filter keys where key > 0 and freq[key] >= key
        candidates = list(filter(lambda x: x > 0 and freq[x] >= x, freq))
        return max(candidates) if candidates else -1
    else:
        # For string input: return the greatest string by lex order that appears at least once (freq >= 1)
        # Since freq is always >=1 for keys, just return max key
        return max(freq)


