def total_match(lst1, lst2):
    # Check if either list contains strings
    has_str = any(isinstance(x, str) for x in lst1 + lst2)
    if has_str:
        # Find the longest string across both lists
        # If multiple longest, max returns the first encountered
        longest = max((x for x in lst1 + lst2 if isinstance(x, str)), key=len)
        return longest

    # Both lists contain only integers (or are empty)
    # Compute total digits in each list
    def digits_count(lst):
        # map abs and str, then sum lengths
        return sum(len(str(abs(x))) for x in lst)

    d1, d2 = digits_count(lst1), digits_count(lst2)
    # If equal, return lst1
    if d1 <= d2:
        chosen = lst1
    else:
        chosen = lst2

    # Sort chosen list ascending but keep original order of equal elements.
    # The problem states "order of the output list must be in ascending order but at the same time maintain its original order"
    # This is ambiguous, but usually means stable sort (sort ascending but stable)
    # sort() in python is stable, so just sort ascending.
    chosen_sorted = sorted(chosen)

    # Return as space-separated string
    return ' '.join(str(x) for x in chosen_sorted)


