        if shift == n:
            return False
        # Right shift by 'shift' means last 'shift' elements move to front
        rotated = arr[-shift:] + arr[:-shift] if shift != 0 else arr
        if is_sorted(rotated):
            return shift
        return check_shift(shift + 1)

