def maximum(arr, k):
    # If k is 0, return an empty list immediately
    if k == 0:
        return []

    # Find the maximum k elements using a simple selection approach without built-in sorting
    # Since constraints require no built-in sorting and O(1) time complexity (impractical),
    # we prioritize correctness and simplicity.
    # We'll extract the k largest elements by repeatedly finding the max and removing it.
    # This is O(k * n) which is acceptable for small arrays and given constraints.

    # Copy arr so we don't modify the original
    temp = arr[:]
    max_elements = []
    for _ in range(k):
        max_val = temp[0]
        max_idx = 0
        for i in range(1, len(temp)):
            if temp[i] > max_val:
                max_val = temp[i]
                max_idx = i
        max_elements.append(max_val)
        # Remove the found max element to find the next max
        temp.pop(max_idx)

    # Now, sort max_elements ascending using a simple insertion sort (no built-in sorting)
    for i in range(1, len(max_elements)):
        key = max_elements[i]
        j = i - 1
        while j >= 0 and max_elements[j] > key:
            max_elements[j + 1] = max_elements[j]
            j -= 1
        max_elements[j + 1] = key

    return max_elements


