def digits(n):
    s = str(n)
    odd_digits = [d for d in s if int(d) % 2 == 1]
    even_digits = [d for d in s if int(d) % 2 == 0]

    if not odd_digits:
        # all digits even -> return '0' (string)
        return '0'
    if not even_digits:
        # all digits odd -> return 0 (int)
        return 0

    # product of odd digits as integer
    odd_product = 1
    for d in odd_digits:
        odd_product *= int(d)

    # product of even digits as integer
    even_product = 1
    for d in even_digits:
        even_product *= int(d)

    # Return product of odd digits as int, product of even digits as int
    # But task says return product of odd digits as string and product of even digits as int.
    # However, user clarified digits(235) returns int 15, so:
    # Odd digits product returned as int, even digits product as int.

    # The examples are ambiguous, but user answer overrides:
    # So return the product of odd digits if any odd digits exist, else product of even digits.
    # But original task says return both? The examples show just one value.

    # From examples:
    # digits(235) == 15  (odd product)
    # digits(246) == 0   (all odd digits product 0)
    # digits(4) == "0"   (all even digits -> '0')
    # digits(1) == 1     (all odd digits -> 0)
    # digits("235") == "15" (string odd product)

    # User clarified digits(235) returns int 15, not string.

    # From the examples, when input is int, return int odd product or 0.
    # When input is str, return string odd product or '0'.

    # So:
    # If input is int, return odd product (int) if any odd digits, else 0 (int)
    # If input is str, return odd product (str) if any odd digits, else '0' (str)

    # So ignoring even digits product.

    if isinstance(n, int):
        return odd_product
    else:
        return str(odd_product)


