def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)
    # Since elements are unique, we can find the index of the smallest element
    min_index = arr.index(min(arr))

    # Rotate array so that min element is at index 0
    rotated = arr[min_index:] + arr[:min_index]

    # Check if rotated array is sorted non-decreasing
    for i in range(n - 1):
        if rotated[i] > rotated[i + 1]:
            return False
    return True


