def order_by_points(nums):
    def digit_sum(n):
        s = str(abs(n))
        if n < 0:
            # first digit negative, rest positive
            first = -int(s[0])
            rest = sum(int(d) for d in s[1:])
            return first + rest
        else:
            return sum(int(d) for d in s)

    return sorted(enumerate(nums), key=lambda x: (digit_sum(x[1]), x[0])) and [x[1] for x in sorted(enumerate(nums), key=lambda x: (digit_sum(x[1]), x[0]))]


