def parse_nested_parens(text):
    groups = text.split()
    depths = []
    for group in groups:
        max_depth = 0
        current_depth = 0
        for ch in group:
            if ch == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ')':
                current_depth -= 1
                if current_depth < 0:
                    raise ValueError(f"Unbalanced parentheses in group: {group}")
            else:
                raise ValueError(f"Invalid character in group: {group}")
        if current_depth != 0:
            raise ValueError(f"Unbalanced parentheses in group: {group}")
        depths.append(max_depth)
    return depths


