def move_one_ball(seq):
    if not seq:
        return True

    n = len(seq)
    # Since values are distinct, sorted non-decreasing means strictly increasing
    sorted_seq = sorted(seq)

    # Try all possible rightward cyclic shifts (including zero shifts)
    # A rightward cyclic shift by k means the sequence becomes:
    # seq[-k:] + seq[:-k]
    for k in range(n):
        shifted = seq[-k:] + seq[:-k]
        if shifted == sorted_seq:
            return True
    return False


