def parse_music(music_string: str) -> List[int]:
    """
    Parses a string of space-separated tokens representing musical notes in a special ASCII format.
    Each note token starts with a letter A-G followed by zero or more '-' characters.
    The length in beats of each note is 1 plus the count of '-' characters following the note letter.
    Returns a list of integers indicating how many beats each note lasts.
    """
    tokens = music_string.strip().split()
    result = []
    for token in tokens:
        if not token:
            continue
        # first character is note A-G
        # rest are dashes indicating added beats
        length = 1 + token[1:].count('-')
        result.append(length)
    return result


