def solve(s):
    result = []
    for ch in s:
        if ch.isdigit():
            # Reverse digits: '1234' -> '4321'
            # Since digits are reversed in whole string, here just keep digit as is,
            # but we will reverse entire digits sequence at the end
            # However, examples show entire string reversed if all digits
            # So for mixed string, digits keep position but to match example "#a@C" -> "#A@c"
            # So it seems digit reversal only when entire string digits
            # So for mixed string, digits keep place, no case change
            result.append(ch)
        elif ch.isalpha():
            # If lowercase, uppercase; if uppercase, lowercase
            if ch.islower():
                result.append(ch.upper())
            else:
                result.append(ch.lower())
        else:
            # Non-alphanumeric chars keep as is
            result.append(ch)
    # Now, check if entire string is digits, then reverse whole string
    if s.isdigit():
        return s[::-1]
    return ''.join(result)


