def circular_shift(x, shift):
    """Circular shift the digits of the integer x, shift the digits left or right by shift
    and return the result as a string.
    """
    s = str(abs(x))
    n = len(s)
    if n == 0:
        return s  # empty string case, though x is int so shouldn't happen
    shift = shift % n  # normalize shift to range [0, n-1]
    if shift == 0:
        result = s
    elif shift > 0:
        # positive shift: shift right by 'shift'
        result = s[-shift:] + s[:-shift]
    else:
        # negative shift: shift left by abs(shift)
        shift = -shift
        result = s[shift:] + s[:shift]
    if x < 0:
        result = "-" + result
    return result


