def move_one_ball(arr):
    if not arr:
        return True
    n = len(arr)
    # Count how many places the ordering decreases
    count_decreases = 0
    for i in range(n):
        if arr[i] > arr[(i + 1) % n]:
            count_decreases += 1
            # If there is more than one decrease, it's not possible
            if count_decreases > 1:
                return False
    return True


