def sum_squares(lst):
    """
    This function takes a list of integers. For all entries in the list,
    it squares the integer if its index is a multiple of 3,
    cubes the integer if its index is a multiple of 4 and not a multiple of 3,
    and leaves the integer unchanged otherwise.
    It then returns the sum of all transformed entries.
    """
    total = 0
    for i, val in enumerate(lst):
        if i % 3 == 0:
            total += val ** 2
        elif i % 4 == 0:
            total += val ** 3
        else:
            total += val
    return total


