def parse_nested_parens(paren_string):
    depths = []
    current_depth = 0
    max_depth = 0
    for char in paren_string:
        if char == '(':
            current_depth += 1
            if current_depth > max_depth:
                max_depth = current_depth
        elif char == ')':
            if current_depth > 0:
                depths.append(max_depth)
                current_depth -= 1
                max_depth = current_depth
    return depths


