def prime_length(s):
    """Write a function that takes a string and returns if the string
    length is a prime number or not.
    """
    n = len(s)
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True


