def parse_music(music: str) -> list[int]:
    # Map common duration symbols to integer values
    # Using standard musical note durations where:
    # w = whole note = 1
    # h = half note = 2
    # q = quarter note = 4
    # e = eighth note = 8
    # s = sixteenth note = 16
    # t = thirty-second note = 32
    # x = sixty-fourth note = 64
    # This is a common convention to represent durations by denominators of the note fraction.
    duration_map = {
        'w': 1,
        'h': 2,
        'q': 4,
        'e': 8,
        's': 16,
        't': 32,
        'x': 64,
    }
    result = []
    for c in music.lower():
        if c in duration_map:
            result.append(duration_map[c])
    return result


