import re

def anti_shuffle(data: str) -> str:
    # Split the string by whitespace, keeping the whitespace in the result
    parts = re.split(r'(\s+)', data)
    # For each non-whitespace part, sort characters ascending lexicographically
    for i in range(0, len(parts), 2):
        parts[i] = ''.join(sorted(parts[i]))
    return ''.join(parts)


