def move_one_ball(arr):
    if not arr:
        return True
    n = len(arr)
    # Since all items are distinct, a rotation that results in a sorted array
    # corresponds to the array being a rotated sorted array.
    # Find the number of "drops" where arr[i] > arr[i+1].
    drops = 0
    for i in range(n):
        if arr[i] > arr[(i+1) % n]:
            drops += 1
            if drops > 1:
                return False
    return True


