def max_fill(grid, capacity):
    # Number of rows and columns
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    total_lowerings = 0
    for c in range(cols):
        # Sum water units in the current well (column)
        water_units = sum(grid[r][c] for r in range(rows))
        # Number of lowers needed for this well
        lowers = (water_units + capacity - 1) // capacity
        total_lowerings += lowers

    return total_lowerings


