def select_words(s: str, n: int) -> list:
    vowels = set('aeiouAEIOU')
    if not s:
        return []
    result = []
    length = len(s)
    for start in range(length):
        for end in range(start + 1, length + 1):
            substr = s[start:end]
            # Count non-vowel letters (ignore spaces)
            non_vowels = sum(1 for ch in substr if ch.isalpha() and ch not in vowels)
            if non_vowels == n:
                result.append(substr)
    return result


