def order_by_points(numbers):
    def digit_sum(n):
        s = str(n)
        if s[0] == '-':
            # first digit after minus sign is negative
            first_digit = -int(s[1])
            rest = s[2:]
            total = first_digit + sum(int(d) for d in rest)
        else:
            total = sum(int(d) for d in s)
        return total

    return sorted(numbers, key=digit_sum)


