def decode_shift(s: str):
    """
    Decodes a string encoded by shifting each lowercase letter by 5 positions forward,
    by shifting each lowercase letter 5 positions backward.
    Non-lowercase characters are left unchanged.
    """
    result = []
    for ch in s:
        if 'a' <= ch <= 'z':
            decoded_char = chr((ord(ch) - ord('a') - 5) % 26 + ord('a'))
            result.append(decoded_char)
        else:
            result.append(ch)
    return "".join(result)


