import string

def select_words(s, n):
    vowels = set("aeiou")
    result = []
    for word in s.split():
        # Remove punctuation
        cleaned = ''.join(ch for ch in word if ch.isalpha())
        # Count consonants case-insensitively
        consonant_count = sum(1 for ch in cleaned.lower() if ch.isalpha() and ch not in vowels)
        if consonant_count == n:
            result.append(word)
    return result


