def circular_shift(x, shift):
    s = str(x)
    n = len(s)
    if shift > n:
        return s[::-1]
    # If shift == 0 or shift == n, return original
    shift %= n
    if shift == 0:
        return s
    # Circular shift left by shift
    return s[shift:] + s[:shift]


