import re

def anti_shuffle(s):
    # Split the string into words and spaces, preserving them
    parts = re.findall(r'\S+|\s+', s)
    result = []
    for part in parts:
        if part.isspace():
            # Preserve spaces as is
            result.append(part)
        else:
            # Sort characters in ascending ASCII order
            sorted_word = ''.join(sorted(part))
            result.append(sorted_word)
    return ''.join(result)


