def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)

    # Check if arr is already sorted non-decreasing or non-increasing
    def is_sorted_non_decreasing(a):
        return all(a[i] <= a[i+1] for i in range(len(a)-1))

    def is_sorted_non_increasing(a):
        return all(a[i] >= a[i+1] for i in range(len(a)-1))

    if is_sorted_non_decreasing(arr) or is_sorted_non_increasing(arr):
        return True

    # Try all right shifts and check if any is sorted non-decreasing or non-increasing
    for shift in range(1, n):
        # Perform right shift by 'shift'
        rotated = arr[-shift:] + arr[:-shift]
        if is_sorted_non_decreasing(rotated) or is_sorted_non_increasing(rotated):
            return True

    return False


